import json,hashlib,re

def checked(key,data,generation):
    if not isinstance(key,str) or re.fullmatch(r'[a-z][a-z0-9_-]{0,31}',key) is None:raise ValueError('record key')
    if type(data) is not bytes or not 1<=len(data)<=4096 or type(generation) is not int or generation<1:raise ValueError('bounded payload and generation')

def publish(io,key,data,generation,boundary):
    checked(key,data,generation)
    obj='data/'+key+'/'+str(generation);idx='index/'+key;digest=hashlib.sha256(data).hexdigest()
    try:old=io.read(obj,8192)
    except __import__('rados').ObjectNotFound:old=None
    if old is not None and old!=data:raise ValueError('immutable version collision')
    try:previous=json.loads(io.read(idx,8192))
    except __import__('rados').ObjectNotFound:previous=None
    if previous is not None and previous['generation']>generation:raise ValueError('stale generation')
    io.write_full(obj,data);boundary('data')
    io.write_full(idx,json.dumps({'object':obj,'sha256':digest,'generation':generation},sort_keys=True).encode());boundary('index')

def read(io,key):
    try:index=json.loads(io.read('index/'+key,8192));data=io.read(index['object'],8192)
    except __import__('rados').ObjectNotFound:return None
    if hashlib.sha256(data).hexdigest()!=index['sha256']:return None
    return data

def audit(io):
    names={obj.key for obj in io.list_objects()};used=set();dangling=[]
    for name in sorted(names):
        if not name.startswith('index/'):continue
        index=json.loads(io.read(name,8192));used.add(index['object'])
        try:data=io.read(index['object'],8192)
        except __import__('rados').ObjectNotFound:dangling.append(name);continue
        if hashlib.sha256(data).hexdigest()!=index['sha256']:dangling.append(name)
    return {'orphans':sorted(name for name in names if name.startswith('data/') and name not in used),'dangling':dangling}

