import pathlib,sys,json,hashlib,threading,time,os,secrets
sys.path.insert(0,str(pathlib.Path.cwd()/'checks'));sys.path.insert(0,str(pathlib.Path.cwd()))
import task,rados
from ceph_native import PrivateCeph
assert os.geteuid()==1000
class Interrupted(Exception):pass
with PrivateCeph() as c:
 c.add_osd();c.client.create_pool('s07_atomic')
 with c.client.open_ioctx('s07_atomic') as io:
  key='r'+secrets.token_hex(6);v1=os.urandom(73);v2=os.urandom(127)
  def observed():return {obj.key:io.read(obj.key,8192)for obj in io.list_objects()}
  def native_read(record):
   try:raw=io.read('index/'+record,8192)
   except rados.ObjectNotFound:return None
   index=json.loads(raw)
   assert isinstance(index,dict)and {'object','sha256','generation'}<=set(index),'native index schema'
   assert type(index['generation'])is int and index['generation']>0,'native generation type'
   assert index['object']=='data/'+record+'/'+str(index['generation']),'native object/version path'
   try:payload=io.read(index['object'],8192)
   except rados.ObjectNotFound:return None
   if hashlib.sha256(payload).hexdigest()!=index['sha256']:return None
   return payload
  def read_checked(record,expected):
   before=observed();assert native_read(record)==expected,'teacher native committed bytes differ'
   actual=task.read(io,record)
   assert actual==expected and(type(actual)is bytes if expected is not None else actual is None),'student committed read incorrect'
   assert before==observed(),'read changed native objects'
  def audit_checked(expected):
   before=observed();actual=task.audit(io)
   assert actual==expected,'native reconciliation incomplete'
   assert before==observed(),'audit changed native objects'
  io.write_full('atomic',b'A'*4096);fail=[];done=threading.Event();reads=[]
  def reader():
   while not done.is_set():
    try:reads.append(io.read('atomic',8192))
    except BaseException as e:fail.append(repr(e));return
  t=threading.Thread(target=reader);t.start()
  try:
   for i in range(12):io.write_full('atomic',(b'B'if i%2 else b'A')*4096)
  finally:done.set();t.join(3)
  assert not t.is_alive() and not fail and reads and all(x in(b'A'*4096,b'B'*4096)for x in reads),'native single object atomic observation'
  def boundary_noop(point):pass
  task.publish(io,key,v1,1,boundary_noop);read_checked(key,v1)
  assert io.read('data/'+key+'/1',8192)==v1,'initial data absent'
  for cut in ('data','index'):
   events=[]
   def crash(point):
    events.append(point)
    try:payload_at_boundary=io.read('data/'+key+'/2',8192)
    except rados.ObjectNotFound:raise AssertionError('new native data missing at write boundary')
    assert payload_at_boundary==v2,'new native data wrong at write boundary'
    read_checked(key,v1 if point=='data'else v2)
    if point==cut:raise Interrupted(point)
   try:task.publish(io,key,v2,2,crash)
   except Interrupted:pass
   else:raise AssertionError('publish swallowed interruption')
   assert events==(['data']if cut=='data'else ['data','index']),'write boundary callback omitted'
   read_checked(key,v1 if cut=='data'else v2)
   audit_checked({'orphans':['data/'+key+('/2'if cut=='data'else '/1')],'dangling':[]})
   if cut=='data':io.remove_object('data/'+key+'/2')
  task.publish(io,key,v2,2,boundary_noop);read_checked(key,v2)
  before=observed();task.publish(io,key,v2,2,boundary_noop)
  assert before==observed(),'same version retry not idempotent';read_checked(key,v2)
  for payload,version in ((os.urandom(31),2),(b'stale',1)):
   try:task.publish(io,key,payload,version,boundary_noop)
   except ValueError:pass
   else:raise AssertionError('conflicting or stale version accepted')
  assert before==observed(),'rejected update mutated native objects';read_checked(key,v2)
  missing='m'+secrets.token_hex(6);corrupt='c'+secrets.token_hex(6)
  io.write_full('index/'+missing,json.dumps({'object':'data/'+missing+'/1','sha256':hashlib.sha256(b'gone').hexdigest(),'generation':1}).encode())
  io.write_full('data/'+corrupt+'/1',b'wrong');io.write_full('index/'+corrupt,json.dumps({'object':'data/'+corrupt+'/1','sha256':hashlib.sha256(b'expected').hexdigest(),'generation':1}).encode())
  read_checked(missing,None);read_checked(corrupt,None)
  audit_checked({'orphans':['data/'+key+'/1'],'dangling':sorted(['index/'+corrupt,'index/'+missing])})
  native_before=observed()
  for record,payload,generation in [('bad/key',b'x',1),('a',b'',1),('a',b'x'*4097,1),('a',b'x',True),('a',b'x',0)]:
   try:task.publish(io,record,payload,generation,boundary_noop)
   except ValueError:pass
   else:raise AssertionError('invalid bounded record accepted')
  assert native_before==observed(),'invalid input altered native store'
